const RENDER_GEOMETRY_EMPTY: RenderGeometry = RenderGeometry(
vec2f(0.0),
vec2f(0.0),
vec2f(0.0),
vec2f(0.0),
0.0,
0.0,
0u,
0u,
0u,
0u
);

// ---------------------------------------------------------------------------------------------------------------------
// Triangles
// ---------------------------------------------------------------------------------------------------------------------

struct RenderGeometryTri {
