bitcast<f32>(geometry[offset + 8u]),
bitcast<f32>(geometry[offset + 9u]),
bitcast<f32>(geometry[offset + 10u]),
bitcast<f32>(geometry[offset + 11u]),
bitcast<f32>(geometry[offset + 12u]),
bitcast<f32>(geometry[offset + 13u]),
bitcast<f32>(geometry[offset + 14u]),
bitcast<f32>(geometry[offset + 15u])
);
}

fn read_vertex_position(index: u32) -> vec2f {
let offset = storage_offsets.geometry_vertex + index * 2u;
return vec2f(
bitcast<f32>(geometry[offset + 0u]),
bitcast<f32>(geometry[offset + 1u])
);
}

fn read_covertex_tangent(index: u32) -> vec2f {
let offset = storage_offsets.geometry_covertex + index * 2u;
return vec2f(
bitcast<f32>(geometry[offset + 0u]),
bitcast<f32>(geometry[offset + 1u])
);
}

fn read_edge_cubic(index: u32) -> Cubic2 {
let offset = storage_offsets.geometry_edge + index * 8u;
return Cubic2(
vec2f(bitcast<f32>(geometry[offset + 0u]), bitcast<f32>(geometry[offset + 1u])),
vec2f(bitcast<f32>(geometry[offset + 2u]), bitcast<f32>(geometry[offset + 3u])),
vec2f(bitcast<f32>(geometry[offset + 4u]), bitcast<f32>(geometry[offset + 5u])),
vec2f(bitcast<f32>(geometry[offset + 6u]), bitcast<f32>(geometry[offset + 7u]))
);
}
// end import "storage/geometry.wgsl"

// import "geometry/cubic.wgsl"
fn cubic2_reversed(c: Cubic2) -> Cubic2 {
return Cubic2(c.p3, c.p2, c.p1, c.p0);
}

fn cubic2_transform(c: Cubic2, m: mat4x4f) -> Cubic2 {
return Cubic2(
(m * vec4f(c.p0, 0.0, 1.0)).xy,
(m * vec4f(c.p1, 0.0, 1.0)).xy,
(m * vec4f(c.p2, 0.0, 1.0)).xy,
(m * vec4f(c.p3, 0.0, 1.0)).xy
);
}

// Evaluates the cubic bezier at parameter [t].
fn cubic2_pos(c: Cubic2, t: f32) -> vec2f {
let mt = 1.0 - t;
let mt2 = mt * mt;
let t2 = t * t;

return c.p0 * (mt2 * mt) + c.p1 * (3.0 * mt2 * t) + c.p2 * (3.0 * mt * t2) + c.p3 * (t2 * t);
}

// Evaluates the tangent of the cubic bezier at parameter [t].
fn cubic2_tan(c: Cubic2, t: f32) -> vec2f {
let mt = 1.0 - t;
let mt2 = mt * mt;
let t2 = t * t;
return (c.p1 - c.p0) * (3.0 * mt2) + (c.p2 - c.p1) * (6.0 * mt * t) + (c.p3 - c.p2) * (3.0 * t2);
}

// Evaluates the acceleration of the cubic bezier at parameter [t].
fn cubic2_acc(c: Cubic2, t: f32) -> vec2f {
let mt = 1.0 - t;
return (c.p2 - 2.0 * c.p1 + c.p0) * (6.0 * mt) + (c.p3 - 2.0 * c.p2 + c.p1) * (6.0 * t);
}

// Evaluates the position and the tangent of the cubic bezier at parameter [t].
fn cubic2_pos_tan(c: Cubic2, t: f32) -> array<vec2f, 2> {
let mt = 1.0 - t;
let mt2 = mt * mt;
let t2 = t * t;

let pos = c.p0 * (mt2 * mt) + c.p1 * (3.0 * mt2 * t) + c.p2 * (3.0 * mt * t2) + c.p3 * (t2 * t);
let tan = (c.p1 - c.p0) * (3.0 * mt2) + (c.p2 - c.p1) * (6.0 * mt * t) + (c.p3 - c.p2) * (3.0 * t2);
return array<vec2f, 2>(pos, tan);
}

// Returns the number of line segments needed to approximate the cubic bezier within the given tolerance.
fn cubic2_wang(c: Cubic2, tolerance: f32) -> f32 {
let v1 = c.p2 - 2.0 * c.p1 + c.p0;
let v2 = c.p3 - 2.0 * c.p2 + c.p1;
let m = max(dot(v1, v1), dot(v2, v2));
if (m < 1.0e-6) { return 1.0; }
return sqrt(sqrt(m) * 3.0 / (4.0 * tolerance));
}

// Splits the cubic bezier at [t].
fn cubic2_split_at(c: Cubic2, t: f32) -> array<Cubic2, 2> {
let p01 = mix(c.p0, c.p1, t);
let p12 = mix(c.p1, c.p2, t);
let p23 = mix(c.p2, c.p3, t);

let p012 = mix(p01, p12, t);
let p123 = mix(p12, p23, t);

let p0123 = mix(p012, p123, t);

return array<Cubic2, 2>(
Cubic2(c.p0, p01, p012, p0123),
Cubic2(p0123, p123, p23, c.p3)
);
}

// Returns the cubic bezier piece between [t0] and [t1].
fn cubic2_piece_at(c: Cubic2, t0: f32, t1: f32) -> Cubic2 {
let pos_tan_t0 = cubic2_pos_tan(c, t0);
let pos_tan_t1 = cubic2_pos_tan(c, t1);
let dt = (t1 - t0) / 3.0;

return Cubic2(
pos_tan_t0[0],
pos_tan_t0[0] + pos_tan_t0[1] * dt,
pos_tan_t1[0] - pos_tan_t1[1] * dt,
pos_tan_t1[0]
);
}

fn cubic2_bbox(c: Cubic2) -> array<vec2f, 2> {
var lo = min(c.p0, min(c.p1, min(c.p2, c.p3)));
var hi = max(c.p0, max(c.p1, max(c.p2, c.p3)));
return array<vec2f, 2>(lo, hi);
}
// end import "geometry/cubic.wgsl"


@group(0) @binding(0) var<uniform> world: World;
@group(0) @binding(1) var<uniform> storage_offsets: StorageOffsets;

@group(1) @binding(0) var<storage, read> geometry: array<u32>;
@group(2) @binding(2) var<storage, read> render_geometry: array<RenderGeometry>;
@group(3) @binding(0) var<storage, read> decorations: array<DecorationEntry>;

struct VtxOut {
@builtin(position) clip_pos: vec4f,
@location(0) world_position: vec2f,
@location(1) local_position: vec2f,
@location(2) @interpolate(flat) cell: u32,
@location(3) @interpolate(flat) decoration_kind: u32,
@location(4) @interpolate(flat) decoration_v0: f32,
@location(5) @interpolate(flat) decoration_v1: f32,
@location(6) @interpolate(flat) decoration_v2: f32,
@location(7) @interpolate(flat) decoration_v3: f32,
}

fn to_clip(p: vec2f) -> vec4f {
let ndc = vec2f((p.x / world.viewport.x * 2.0) - 1.0, 1.0 - (p.y / world.viewport.y * 2.0));
return vec4f(ndc, 0.0, 1.0);
}

@vertex
fn vs_main(@builtin(vertex_index) vertex_index: u32) -> VtxOut {
let geom = render_geometry[vertex_index / 6u];
let kind = geom.flags;
let frame_index = geom.frame_index;
let inverse_world_transform = read_frame_inverse_transform(frame_index);

var decoration: DecorationEntry;
if (geom.decoration_index == NONE) {
decoration = DECORATION_NONE;
}
else {
decoration = decorations[geom.decoration_index];
}

var position_world = vec2f(0.0);

if (kind == RENDER_GEOMETRY_KIND_TRI) {
let tri = render_geometry_read_tri(geom);

switch(vertex_index % 6u) {
case 0u: { position_world = tri.p0; }
case 1u: { position_world = tri.p1; }
case 2u: { position_world = tri.p2; }
default: { position_world = tri.p0; }
};
}
else if (kind == RENDER_GEOMETRY_KIND_QUAD) {
let quad = render_geometry_read_quad(geom);

switch(vertex_index % 6u) {
case 0u:     { position_world = quad.p0; }
case 1u, 4u: { position_world = quad.p1; }
case 2u, 3u: { position_world = quad.p2; }
case 5u:     { position_world = quad.p3; }
default: {}
};
}

let position_local = (inverse_world_transform * vec4f(position_world, 0.0, 1.0)).xy;
let position_screen = world.world_to_screen * vec4f(position_world, 0.0, 1.0);
var out = VtxOut();
out.clip_pos = to_clip(position_screen.xy);
out.world_position = position_world;
out.local_position = position_local;
out.cell = geom.cell;
out.decoration_kind = decoration.kind;
out.decoration_v0 = decoration.v0;
out.decoration_v1 = decoration.v1;
out.decoration_v2 = decoration.v2;
out.decoration_v3 = decoration.v3;
return out;
}

// %MARK% USER FRAGMENT SHADER SLOT


@fragment
fn fs_main(in: VtxOut) -> @location(0) vec4f {
let decoration_kind = in.decoration_kind;

if (decoration_kind == DECORATION_KIND_COLOR) {
let color = vec4f(in.decoration_v0, in.decoration_v1, in.decoration_v2, in.decoration_v3);
return color;
}
else if (decoration_kind == DECORATION_KIND_FRAGMENT_SHADER) {
let index = bitcast<u32>(in.decoration_v0);
var color = vec4f(0.0);
switch(index) {
// % MARK% USER FRAGMENT SHADER SELECTOR SLOT
default: { }
}

return color;
}

return vec4f(0.0, 0.0, 0.0, 1.0);
}

''';

